/** Native offline Android UI; no WebView and no networking code. */
public final class MainActivity extends Activity {
    private static final int BG=0xff101410,CARD=0xff20271d,GREEN=0xffb6f552,TEXT=0xfff0f5eb,MUTED=0xffa6b29c;
    private static final int CREATE_FILE=41,OPEN_FILE=42,OPEN_RECEIPT=43;
    private final ExecutorService io=Executors.newSingleThreadExecutor();
    private Store store;private Store.Snapshot state;private LinearLayout root,body,nav;private TextView status;
    private RefundStore.View refundState;private Ledger.Event pendingStripe;private boolean firstResume=true;
    private long operatingExpenses=0;private int tab=0,historyLimit=100;private boolean busy=false,dead=false;private String message="Records and receipts stay on this device.",exportKind="backup";
    private String receiptEventId; private CatalogStore.View catalog; private String selectedProduct=Catalog.LEGACY;
    private Uri deferredDocument;private int deferredRequest;
    private final List<View> controls=new ArrayList<>();
    @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);if(saved!=null){receiptEventId=saved.getString("receiptEventId");selectedProduct=saved.getString("selectedProduct",Catalog.LEGACY);tab=saved.getInt("tab",0);exportKind=saved.getString("exportKind","backup");deferredRequest=saved.getInt("deferredRequest",0);String document=saved.getString("deferredDocument");if(document!=null)deferredDocument=Uri.parse(document);}store=new Store(this);buildRoot();job(()->{var pending=store.recoverPending();if(pending!=null){store.acknowledge(pending.id());message="Recovered the last save exactly once.";}pendingStripe=store.checkout();return overview();},s->{state=s;render();});}
    private Store.Snapshot overview(){var db=store.database();db.beginTransaction();try{var s=store.snapshot();operatingExpenses=new BusinessStore(store).view().expenses();catalog=new CatalogStore(store).view();refundState=new RefundStore(store).view();pendingStripe=store.checkout();db.setTransactionSuccessful();return s;}finally{db.endTransaction();}}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("receiptEventId",receiptEventId);b.putString("selectedProduct",selectedProduct);b.putInt("tab",tab);b.putString("exportKind",exportKind);b.putInt("deferredRequest",deferredRequest);if(deferredDocument!=null)b.putString("deferredDocument",deferredDocument.toString());}
    @Override protected void onDestroy(){dead=true;io.execute(store::close);io.shutdown();super.onDestroy();}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private GradientDrawable background(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private TextView text(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(5),0,dp(5));return v;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private void buildRoot(){root=column();root.setBackgroundColor(BG);root.setPadding(dp(16),0,dp(16),0);root.setOnApplyWindowInsetsListener((v,insets)->{root.setPadding(dp(16),insets.getSystemWindowInsetTop(),dp(16),insets.getSystemWindowInsetBottom());return insets;});setContentView(root);root.requestApplyInsets();TextView title=text("Monster Tracker",24,TEXT);title.setTypeface(null,Typeface.BOLD);root.addView(title);status=text(message,13,MUTED);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);root.addView(status);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=column();body.setPadding(0,dp(8),0,dp(20));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);root.addView(nav,new LinearLayout.LayoutParams(-1,dp(64)));}
    private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(16);b.setTextColor(TEXT);b.setBackground(background(CARD,14));b.setMinHeight(dp(56));b.setPadding(dp(10),dp(10),dp(10),dp(10));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,dp(5));b.setLayoutParams(p);b.setOnClickListener(v->{if(!busy)action.run();});b.setEnabled(!busy);controls.add(b);return b;}
    private void addButton(String s,Runnable r){body.addView(button(s,r));}
    private void heading(String s){TextView h=text(s,23,TEXT);h.setTypeface(null,Typeface.BOLD);body.addView(h);}
    private void paragraph(String s){body.addView(text(s,15,MUTED));}
    private EditText field(LinearLayout parent,String label,String initial,int type){parent.addView(text(label,15,TEXT));EditText e=new EditText(this);e.setTextColor(TEXT);e.setHintTextColor(MUTED);e.setTextSize(18);e.setInputType(type);e.setText(initial);e.setSingleLine(type!=InputType.TYPE_CLASS_TEXT);e.setPadding(dp(12),dp(12),dp(12),dp(12));e.setBackground(background(CARD,10));e.setMinHeight(dp(54));parent.addView(e,new LinearLayout.LayoutParams(-1,-2));controls.add(e);return e;}
    private EditText amount(String label,long cents){return field(body,label,Ledger.inputMoney(cents),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);}
    private RadioGroup choices(String label,String[] values,String[] names,Consumer<String> change){body.addView(text(label,15,TEXT));RadioGroup g=new RadioGroup(this);g.setOrientation(RadioGroup.HORIZONTAL);for(int i=0;i<values.length;i++){RadioButton r=new RadioButton(this);r.setId(View.generateViewId());r.setTag(values[i]);r.setText(names[i]);r.setTextColor(TEXT);r.setTextSize(16);r.setMinHeight(dp(52));g.addView(r,new RadioGroup.LayoutParams(0,-2,1));controls.add(r);}g.check(g.getChildAt(0).getId());g.setOnCheckedChangeListener((group,id)->{RadioButton r=group.findViewById(id);if(r!=null)change.accept((String)r.getTag());});body.addView(g);return g;}
    private String selected(RadioGroup g){return (String)g.findViewById(g.getCheckedRadioButtonId()).getTag();}
    private void render(){if(dead)return;controls.clear();body.removeAllViews();nav.removeAllViews();status.setText(message+(busy?" · Saving…":""));String[] labels={"Home","Sale","Stock","History","Settings"};for(int i=0;i<labels.length;i++){final int index=i;Button b=button(labels[i],()->{tab=index;render();});b.setTextSize(11);b.setTextColor(tab==i?BG:MUTED);b.setBackground(background(tab==i?GREEN:BG,8));nav.addView(b,new LinearLayout.LayoutParams(0,-1,1));}if(state==null){paragraph("Opening local database…");return;}if(pendingStripe!=null){paragraph("A Stripe payment is pending; its cans are reserved. Other available stock can be sold offline. Check this payment before recording the same customer again.");addButton("Resume / check pending Stripe payment",()->startActivity(new Intent(this,StripeActivity.class)));}switch(tab){case 0->dashboard();case 1->sale();case 2->stock();case 3->history();case 4->settings();}}
    private void metric(String label,String value){LinearLayout c=column();c.setPadding(dp(16),dp(12),dp(16),dp(12));c.setBackground(background(CARD,16));c.addView(text(label,14,MUTED));TextView v=text(value,28,TEXT);v.setTypeface(null,Typeface.BOLD);c.addView(v);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));body.addView(c,p);}
    private void dashboard(){var t=state.totals();addButton("Profit & financial reports",()->startActivity(new Intent(this,ReportsActivity.class)));heading("Your stock, at a glance");LinearLayout hero=column();hero.setPadding(dp(20),dp(16),dp(20),dp(16));hero.setBackground(background(GREEN,22));hero.addView(text("CANS REMAINING",14,BG));TextView count=text(Long.toString(catalog.stock().values().stream().mapToLong(Long::longValue).sum()),64,BG);count.setTypeface(null,Typeface.BOLD);hero.addView(count);hero.addView(text("Available to sell · AUD · Perth time",14,BG));if(pendingStripe!=null)hero.addView(text(pendingStripe.quantity()+" cans reserved for pending Stripe",14,BG));body.addView(hero);addButton("Record a sale",()->{tab=1;render();});long low=catalog.shopping().stream().filter(Catalog.Shopping::low).count();if(low>0)addButton(low+" flavour(s) low / out of stock — shopping list",()->startActivity(new Intent(this,CatalogActivity.class).putExtra("showShopping",true)));metric("Gross cans sold",Long.toString(t.sold()));metric("Recorded singles / two-can deals",t.singles()+" / "+t.deals());metric("Missing / damaged / lost",Long.toString(t.missing()));metric("Cash funds from recorded sales",Ledger.money(FundsStore.balance(store.database(),"cash")));metric("Card funds from recorded sales",Ledger.money(FundsStore.balance(store.database(),"card")));metric("Gross sales revenue",Ledger.money(t.revenue()));metric("Recorded successful refunds",Ledger.money(refundState.state().amount()));metric("Net revenue",Ledger.money(t.revenue()-refundState.state().amount()));metric("Cash / card revenue",Ledger.money(t.cash()-refundState.state().cash())+" / "+Ledger.money(t.card()-refundState.state().card()));metric("Purchase costs",Ledger.money(t.purchases()));metric("Recorded card/refund fees",Ledger.money(t.fees()+refundState.state().fees()));metric("Cash result after stock & refunds",Ledger.money(t.result()-refundState.state().amount()-refundState.state().fees()));metric("Operating expenses",Ledger.money(operatingExpenses));metric("Result after stock & expenses",Ledger.money(t.result()-operatingExpenses-refundState.state().amount()-refundState.state().fees()));paragraph("Cash result = all revenue − card fees − all purchase costs. Manual card entry records payment only. Opening dates remain unknown. Refunds and extra fees are separate; unverified additional refund fees: "+refundState.state().unknownFees()+".");}
    private void productPicker(){body.addView(text("Monster flavour",15,TEXT));Spinner picker=new Spinner(this);String[] names=catalog.products().stream().map(p->p.name()+" · "+catalog.stock().getOrDefault(p.id(),0L)+" cans").toArray(String[]::new);picker.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));for(int i=0;i<catalog.products().size();i++)if(catalog.products().get(i).id().equals(selectedProduct))picker.setSelection(i);picker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int position,long id){selectedProduct=catalog.products().get(position).id();}});body.addView(picker);controls.add(picker);}
    private void sale(){heading("Record sale");productPicker();addButton("Scan product barcode",()->startActivityForResult(new Intent(this,CameraActivity.class).putExtra("mode","barcode"),64));paragraph(catalog.stock().values().stream().mapToLong(Long::longValue).sum()+" cans available (pending Stripe stock is reserved)");final String[] type={"single"};RadioGroup quantity=choices("Quantity",new String[]{"single","deal"},new String[]{"1 can","2-can deal"},s->{});EditText price=amount("Sale total (AUD)",state.prices().single());quantity.setOnCheckedChangeListener((g,id)->{type[0]=selected(quantity);price.setText(Ledger.inputMoney(type[0].equals("single")?state.prices().single():state.prices().deal()));});RadioGroup payment=choices("Payment",new String[]{"cash","card"},new String[]{"Cash","Card"},s->{});EditText fee=amount("Actual card fee (AUD)",0);fee.setEnabled(false);payment.setOnCheckedChangeListener((g,id)->{boolean card=selected(payment).equals("card");fee.setEnabled(card&&!busy);if(!card)fee.setText("0.00");});long[] when={System.currentTimeMillis()};Button date=button(Ledger.displayTime(when[0]),()->pickTime(when,()->{}));date.setOnClickListener(v->{if(!busy)pickTime(when,()->date.setText(Ledger.displayTime(when[0])));});body.addView(text("Sale date & time (Perth)",15,TEXT));body.addView(date);EditText note=field(body,"Optional note","",InputType.TYPE_CLASS_TEXT);Button confirm=button("Confirm sale",()->{try{String kind=selected(quantity),pay=selected(payment);var event=Ledger.event(kind,kind.equals("single")?1:2,pay,Ledger.cents(price.getText().toString()),pay.equals("card")?Ledger.cents(fee.getText().toString()):0,0,note.getText().toString(),when[0],null);save(event,"Sale saved locally.");}catch(Exception e){error(e);}});body.addView(confirm);confirm.setEnabled(state.totals().stock()>=1&&!busy);addButton(new PaymentSettings(this).live()?"Charge with Stripe Tap to Pay":"Try Stripe Tap to Pay (test mode)",()->{try{if(!new PaymentSettings(this).configured()){new AlertDialog.Builder(this).setTitle("Set up Stripe first").setMessage("Create your Stripe account and pair a secure payment backend in Settings. Test payments do not affect your real stock or revenue.").setPositiveButton("Settings",(d,w)->{tab=4;render();}).setNegativeButton("Close",null).show();return;}String kind=selected(quantity);var event=Ledger.event(kind,kind.equals("single")?1:2,"card",Ledger.cents(price.getText().toString()),0,0,note.getText().toString(),when[0],null);if(event.revenue()<50)throw new IllegalArgumentException("Stripe minimum payment is AUD $0.50.");job(()->{new CatalogStore(store).stage(event,selectedProduct,true);pendingStripe=event;return overview();},snapshot->{state=snapshot;render();startActivity(new Intent(this,StripeActivity.class));});}catch(Exception ex){error(ex);}});paragraph("Confirm sale records cash or a card payment taken elsewhere. Stripe Tap to Pay takes payment through Stripe and requires internet. Test payments never change your real ledger.");}
    private void pickTime(long[] when,Runnable changed){ZonedDateTime z=Instant.ofEpochMilli(when[0]).atZone(Ledger.PERTH);new DatePickerDialog(this,(view,year,month,day)->new TimePickerDialog(this,(time,hour,minute)->{try{when[0]=LocalDateTime.of(year,month+1,day,hour,minute).atZone(Ledger.PERTH).toInstant().toEpochMilli();changed.run();}catch(Exception e){error(e);}},z.getHour(),z.getMinute(),true).show(),z.getYear(),z.getMonthValue()-1,z.getDayOfMonth()).show();}
    private void stock(){heading("Stock");productPicker();addButton("Flavours, barcodes & shopping list",()->startActivity(new Intent(this,CatalogActivity.class)));addButton("Supplier purchases, receipts & expenses",()->startActivity(new Intent(this,BusinessActivity.class)));metric("Available inventory",Long.toString(catalog.stock().values().stream().mapToLong(Long::longValue).sum()));paragraph("Original: 24 cans for $50. Four opening missing cans have an unknown date.");TextView h=text("Add purchased stock",20,TEXT);body.addView(h);EditText q=field(body,"Cans purchased","24",InputType.TYPE_CLASS_NUMBER);EditText cost=amount("Total purchase cost (AUD)",5000);EditText gst=amount("Actual GST shown on receipt (AUD; zero if none)",0);EditText note=field(body,"Purchase note","",InputType.TYPE_CLASS_TEXT);addButton("Confirm purchase",()->{try{save(Ledger.event("restock",quantity(q),"none",0,0,Ledger.cents(cost.getText().toString()),note.getText().toString(),System.currentTimeMillis(),null),"Stock purchase saved.",Ledger.cents(gst.getText().toString()));}catch(Exception e){error(e);}});body.addView(text("Missing, damaged or lost",20,TEXT));RadioGroup kind=choices("Reason",new String[]{"missing","damaged","lost"},new String[]{"Missing","Damaged","Lost"},s->{});EditText loss=field(body,"Cans removed","1",InputType.TYPE_CLASS_NUMBER);EditText lossNote=field(body,"Optional details","",InputType.TYPE_CLASS_TEXT);addButton("Confirm stock removal",()->{try{save(Ledger.event(selected(kind),quantity(loss),"none",0,0,0,lossNote.getText().toString(),System.currentTimeMillis(),null),"Stock adjustment saved; no sale revenue.");}catch(Exception e){error(e);}});}
    private long quantity(EditText e){try{long n=Long.parseLong(e.getText().toString().trim());if(n<1||n>10000)throw new NumberFormatException();return n;}catch(NumberFormatException ex){throw new IllegalArgumentException("Quantity must be 1–10,000 cans.");}}
    private void history(){heading("Transaction history");paragraph("Tap a record for details or traceable undo. No transaction can be deleted.");Set<String> corrected=new HashSet<>();for(var e:state.events())if(e.type().equals("undo"))corrected.add(e.target());int shown=0;for(int i=state.events().size()-1;i>=0&&shown<historyLimit;i--,shown++){var e=state.events().get(i);String label=e.type().equals("undo")?"UNDO / CORRECTION":e.type().toUpperCase(Locale.ENGLISH)+" · "+e.quantity()+" cans";if(e.revenue()>0)label+=" · "+Ledger.money(e.revenue());if(corrected.contains(e.id()))label+=" · corrected";String finalLabel=label;addButton(finalLabel+"\n"+Ledger.displayTime(e.timestamp()),()->details(e,corrected.contains(e.id())));}if(state.events().size()>historyLimit)addButton("Show 100 more",()->{historyLimit+=100;render();});}
    private void details(Ledger.Event e,boolean corrected){if(Ledger.set("single","deal").contains(e.type())){new AlertDialog.Builder(this).setTitle("Sale actions").setItems(new String[]{"View details / traceable undo","Refunds & returned goods"},(dialog,index)->{if(index==1)startActivity(new Intent(this,RefundActivity.class).putExtra("saleId",e.id()));else detailsRecord(e,corrected);}).setNegativeButton("Close",null).show();return;}detailsRecord(e,corrected);}
    private void detailsRecord(Ledger.Event e,boolean corrected){String detail="ID: "+e.id()+"\nEvent date: "+Ledger.displayTime(e.timestamp())+"\nUTC: "+(e.timestamp()==null?"Unknown":Ledger.iso(e.timestamp()))+"\nRecorded on device: "+Ledger.displayTime(e.recordedAt())+"\nQuantity: "+e.quantity()+"\nPayment: "+e.payment()+"\nRevenue / stored sale price: "+Ledger.money(e.revenue())+"\nActual fee: "+Ledger.money(e.fee())+"\nPurchase cost: "+Ledger.money(e.cost())+"\nNote: "+e.note()+(e.target()==null?"":"\nCorrects: "+e.target());AlertDialog.Builder d=new AlertDialog.Builder(this).setTitle(e.type()+ (corrected?" — corrected":"")).setMessage(detail).setPositiveButton("Close",null);if(!corrected&&!e.type().equals("undo"))d.setNegativeButton("Undo…",(a,b)->undo(e));d.setNeutralButton("Receipt photos",(a,b)->receiptMenu(e));d.show();}
    private void undo(Ledger.Event e){if(e.note().startsWith("Stripe pi_")){new AlertDialog.Builder(this).setTitle("Stripe refund required").setMessage("Undo does not refund a Stripe payment. Refund it in Stripe first. Automated refund reconciliation is not included in this version; keep its payment record and receipt for reconciliation.").setPositiveButton("Close",null).show();return;}EditText reason=new EditText(this);reason.setHint("Reason for correction");reason.setText("Correction of "+e.type());new AlertDialog.Builder(this).setTitle("Undo this transaction?").setMessage("The original remains in history. A new undo record will reverse its effects. To edit a sale, undo it and enter the corrected sale.").setView(reason).setNegativeButton("Cancel",null).setPositiveButton("Confirm undo",(d,w)->{try{save(Ledger.event("undo",0,"none",0,0,0,reason.getText().toString(),System.currentTimeMillis(),e.id()),"Undo saved. Original history retained.");}catch(Exception ex){error(ex);}}).show();}
    private void settings(){heading("Settings & backups");addButton("Encrypted backups, automatic schedule & recovery",()->startActivity(new Intent(this,BackupActivity.class)));addButton("Profit, GST & financial reports",()->startActivity(new Intent(this,ReportsActivity.class)));addButton("Flavours, barcodes & low-stock settings",()->startActivity(new Intent(this,CatalogActivity.class)));addButton("Purchases, receipts, expenses & audit",()->startActivity(new Intent(this,BusinessActivity.class)));stripeSettings();EditText single=amount("Default single price (AUD)",state.prices().single());EditText deal=amount("Default two-can deal (AUD)",state.prices().deal());addButton("Save future sale prices",()->{try{var p=new Ledger.Prices(Ledger.cents(single.getText().toString()),Ledger.cents(deal.getText().toString()));job(()->{store.setPrices(p);return overview();},s->{state=s;message="Future prices saved. Historical amounts unchanged.";render();});}catch(Exception e){error(e);}});addButton("Export full JSON backup",()->createFile("backup"));addButton("Import / restore JSON backup",this::openBackup);addButton("Export sales / stock history CSV",()->createFile("csv"));paragraph("Choose an on-device folder such as Downloads. You can copy JSON backups to a USB drive or another phone without internet. Full JSON backups include your receipt photos. CSV is for viewing history, not restoring.");paragraph("Uninstalling the app, clearing app data, losing or resetting your phone can erase the local database. Export regularly and keep a copy away from this phone. Android cloud backup is disabled. Ordinary JSON backups are not encrypted; use Encrypted backups for portable password protection. Keep backup files and passwords outside this phone.");paragraph("Restore merges validated transactions without overwriting or deleting existing history. Matching IDs are skipped; conflicting IDs and invalid files are rejected. Price settings from the backup require confirmation.");}
    private void save(Ledger.Event e,String success){save(e,success,0);}private void save(Ledger.Event e,String success,long actualGst){String product=selectedProduct;job(()->{if(e.type().equals("undo"))store.stage(e);else new CatalogStore(store).stage(e,product,false,actualGst);store.recoverPending();return overview();},s->{state=s;message=success;tab=0;render();io.execute(()->{try{store.acknowledge(e.id());}catch(Exception ignored){/* next launch safely recovers the same ID */}});});}
    private <T> void job(Callable<T> action,Consumer<T> done){if(busy)return;busy=true;for(View v:controls)v.setEnabled(false);status.setText("Working locally…");io.execute(()->{try{T result=action.call();SheetsSync.requestAutomatic(this);runOnUiThread(()->{if(dead)return;busy=false;done.accept(result);resumeDocument();});}catch(Exception e){runOnUiThread(()->{if(dead)return;busy=false;message="Not saved: "+safeMessage(e);render();error(e);});}});}
    private String safeMessage(Exception e){return e.getMessage()==null?"Operation failed. No records were deleted.":e.getMessage();}
    private void error(Exception e){message=safeMessage(e);if(status!=null)status.setText(message);new AlertDialog.Builder(this).setTitle("Could not complete").setMessage(message).setPositiveButton("OK",null).show();}
    @Override protected void onResume(){super.onResume();if(firstResume){firstResume=false;return;}if(store!=null&&!busy&&!dead)job(()->{pendingStripe=store.checkout();return overview();},s->{state=s;render();});}
    private void sheetsSettings(){
        SheetsSync sync=new SheetsSync(this);heading("Google Sheets");paragraph(sync.status(state.events().size()));
        paragraph(sync.automatic()?"Automatic uploads enabled. Android may delay background uploads to save battery.":"Manual uploads only.");
        addButton("Connect / configure Google Sheets",()->{
            LinearLayout form=column();form.setPadding(dp(16),0,dp(16),0);
            EditText url=field(form,"Apps Script deployment URL",sync.url(),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);
            EditText token=field(form,"Private pairing token (leave blank to keep existing)","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);
            CheckBox auto=new CheckBox(this);auto.setText("Automatically upload saved records");auto.setTextColor(TEXT);auto.setChecked(sync.automatic());form.addView(auto);
            form.addView(text("See SHEETS_SETUP.md in the repository. Receipt photos stay local; uploads include transaction data and notes.",14,MUTED));
            var dialog=new AlertDialog.Builder(this).setTitle("Connect Google Sheets").setView(form).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();
            dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String secret=token.getText().toString().trim();if(secret.isEmpty()&&sync.configured())secret=sync.token();sync.save(url.getText().toString(),secret,auto.isChecked());dialog.dismiss();message="Sheets connected. Initial upload queued; local records retained.";render();}catch(Exception e){error(e);}}));dialog.show();
        });
        addButton("Upload now",()->{if(!sync.configured()){error(new IllegalStateException("Connect your Google Sheets receiver first."));return;}job(()->{sync.upload();return store.snapshot();},s->{state=s;message="Google Sheets upload complete.";render();});});
        addButton("Refresh sync status",()->{message="Sync status refreshed.";render();});
        SheetsSync.schedule(this,false);
    }
    private void stripeSettings(){
        sheetsSettings();
        PaymentSettings pairing=new PaymentSettings(this);body.addView(text("Stripe Tap to Pay",20,TEXT));paragraph(pairing.configured()?(pairing.live()?"Real payment mode configured":"Test mode configured") : "Not connected. Create an Australian Stripe account, then connect your secure payment backend.");
        addButton("Set up / connect Stripe",()->{
            if(pendingStripe!=null){error(new IllegalStateException("Resolve the pending payment before changing Stripe settings."));return;}
            LinearLayout form=column();form.setPadding(dp(16),0,dp(16),0);EditText url=field(form,"Payment backend HTTPS address",pairing.url(),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);EditText token=field(form,"Backend access token (not a Stripe API key)","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);CheckBox live=new CheckBox(this);live.setText("Enable real payments (after successful test)");live.setTextColor(TEXT);live.setChecked(pairing.live());form.addView(live);TextView hint=text("Start in test mode. Pairing details stay on this phone and are not included in backups.",14,MUTED);form.addView(hint);
            var dialog=new AlertDialog.Builder(this).setTitle("Connect Stripe backend").setView(form).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String access=token.getText().toString().trim();if(access.isEmpty()&&pairing.configured())access=pairing.token();pairing.save(url.getText().toString(),access,live.isChecked());dialog.dismiss();message="Payment settings saved. Use a test payment before taking real payments.";render();}catch(Exception ex){error(ex);}}));dialog.show();
        });
        paragraph("Galaxy A16 5G: Android 13+, NFC, current security updates and internet are required. Live Tap to Pay requires Developer options disabled. Stripe requires precise location access only when you use Tap to Pay.");
    }
    private void receiptMenu(Ledger.Event event){
        List<Receipts.Photo> photos=new ArrayList<>();for(var p:state.receipts())if(p.eventId().equals(event.id()))photos.add(p);
        String[] labels=new String[photos.size()+2];labels[0]="Import receipt photo";labels[1]="Take live receipt photo";for(int i=0;i<photos.size();i++)labels[i+2]="View photo "+(i+1)+" · "+Ledger.displayTime(photos.get(i).createdAt());
        new AlertDialog.Builder(this).setTitle("Receipt photos").setItems(labels,(d,index)->{if(index==0){receiptEventId=event.id();Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/*");try{startActivityForResult(intent,OPEN_RECEIPT);}catch(ActivityNotFoundException ex){error(new IllegalStateException("No photo picker available."));}}else if(index==1){receiptEventId=event.id();startActivityForResult(new Intent(this,CameraActivity.class).putExtra("mode","receipt"),66);}else viewReceipt(photos.get(index-2));}).setNegativeButton("Close",null).show();
    }
    private void viewReceipt(Receipts.Photo photo){byte[] bytes=Receipts.bytes(photo);var bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap==null){error(new IllegalStateException("This receipt image could not be displayed."));return;}ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setContentDescription("Receipt photo for this transaction");ScrollView scroll=new ScrollView(this);scroll.addView(image);var dialog=new AlertDialog.Builder(this).setTitle("Receipt photo").setView(scroll).setPositiveButton("Close",null).create();dialog.setOnDismissListener(d->{image.setImageDrawable(null);bitmap.recycle();});dialog.show();}
    private void createFile(String kind){exportKind=kind;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(kind.equals("csv")?"text/csv":"application/json");intent.putExtra(Intent.EXTRA_TITLE,"monster-"+LocalDate.now(Ledger.PERTH)+ (kind.equals("csv")?"-history.csv":"-backup.json"));try{startActivityForResult(intent,CREATE_FILE);}catch(ActivityNotFoundException e){error(new IllegalStateException("No document picker available on this device."));}}
    private void openBackup(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");try{startActivityForResult(intent,OPEN_FILE);}catch(ActivityNotFoundException e){error(new IllegalStateException("No document picker available on this device."));}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;if(request==65){selectedProduct=data.getStringExtra("productId");if(selectedProduct==null)selectedProduct=Catalog.LEGACY;tab=1;return;}if(request==64){try{Catalog.Product product=new CatalogStore(store).lookup(data.getStringExtra("barcode"));if(product==null){startActivityForResult(new Intent(this,CatalogActivity.class).putExtra("barcode",data.getStringExtra("barcode")),65);}else{selectedProduct=product.id();message="Selected "+product.name()+". Review and confirm the sale.";tab=1;render();}}catch(Exception e){error(e);}return;}if(data.getData()==null)return;Uri uri=data.getData();if(busy){deferredDocument=uri;deferredRequest=request;return;}if(request==OPEN_RECEIPT||request==66){String eventId=receiptEventId;if(eventId==null){error(new IllegalStateException("Choose the transaction again before adding a receipt."));return;}job(()->{var photo=Receipts.photo(eventId,PhotoFiles.read(this,uri));store.addReceipt(photo);if(request==66)new File(getCacheDir(),"receipt-camera/"+uri.getLastPathSegment()).delete();return overview();},snapshot->{state=snapshot;message="Receipt photo saved on this phone and included in JSON backups.";render();});}else if(request==CREATE_FILE){String kind=exportKind;job(()->{var s=overview();String content=kind.equals("csv")?Backup.csv(s.events()):Backup.encode(store.fullBackup());try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Could not open destination.");out.write(content.getBytes(StandardCharsets.UTF_8));out.flush();}return uri;},u->{message="Export complete. Keep a copy outside this phone.";render();});}else if(request==OPEN_FILE)job(()->{String content=readBackup(uri);var incoming=Backup.decode(content);var current=overview();var merged=Ledger.merge(current.events(),incoming.events());return new ImportPreview(incoming,merged.size()-current.events().size(),current.events().size());},this::confirmRestore);}
    private void resumeDocument(){if(deferredDocument!=null&&!busy){Uri uri=deferredDocument;int request=deferredRequest;deferredDocument=null;deferredRequest=0;onActivityResult(request,RESULT_OK,new Intent().setData(uri));}}
    private record ImportPreview(Backup.Data data,int added,int current){}
    private void confirmRestore(ImportPreview p){render();new AlertDialog.Builder(this).setTitle("Restore validated backup?").setMessage("Existing records: "+p.current+"\nNew records to add: "+p.added+"\nReceipt photos in backup: "+p.data.receipts().size()+"\nSupplier documents in backup: "+(p.data.business()==null?0:Purchases.list(p.data.business().get("documents")).size())+"\nMatching IDs will be skipped. Saved transactions will not be deleted or overwritten. Future prices, flavour stock settings and GST settings will be restored; saved barcodes must agree.\n\nFuture prices will become "+Ledger.money(p.data.prices().single())+" / "+Ledger.money(p.data.prices().deal())+". Export your current JSON backup first if needed.").setNegativeButton("Cancel",(d,w)->{message="Restore cancelled. No changes.";status.setText(message);}).setPositiveButton("Merge & restore",(d,w)->job(()->{int n=store.importBackup(p.data);return new RestoreResult(n,overview());},r->{state=r.snapshot;message="Restored "+r.count+" new records. Existing history retained.";render();})).show();}
    private record RestoreResult(int count,Store.Snapshot snapshot){}
    private String readBackup(Uri uri)throws IOException {try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("Could not open backup.");byte[] b=new byte[8192];int total=0,n;while((n=in.read(b))!=-1){total+=n;if(total>Backup.MAX_BYTES)throw new IOException("Backup exceeds 64 MB.");out.write(b,0,n);}try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(out.toByteArray())).toString();}catch(CharacterCodingException ex){throw new IOException("Backup is not valid UTF-8.");}}}
}
